SELECT anum, awriter, acontent,adate,row_num FROM ( SELECT anum, awriter, acontent,adate,ROW_NUMBER() OVER(ORDER BY anum desc) AS row_num FROM qna_a
awriter like '%' || #{searchValue} ||'%'
atitle like '%' || #{searchValue} ||'%'
acontent like '%' || #{searchValue} ||'%'
) numbered_rows WHERE row_num BETWEEN #{begin} AND #{end}
